import { colors, Theme, useTheme } from '@/theme'
import {
	Activity,
	Camera,
	Check,
	Eye,
	FileSearch,
	Globe,
	ImageIcon,
	Lightbulb,
	PaintRoller,
	PanelTop,
	Search,
	Settings,
	SquareTerminal,
	Terminal,
	X
} from 'lucide-react-native'
import { PulsingDot } from './PulsingDot'
import { View } from 'react-native'
import { defineStyles } from '@/utils/defineStyles'
import { ThinkingType } from '../utils/llm-tags'
import {
	AssetGenerationAnimationExpo,
	EyeAnimationExpo,
	FileSearchAnimationExpo,
	RollerBrushAnimationExpo,
	SettingsAnimationExpo,
	ThinkingSvgAnimationExpo,
	CodeBrowserAnimationExpo,
	ActivityAnimationExpo,
	SearchSmAnimationExpo,
	GlobeAnimationExpo
} from './animated-svgs'

type IconCmp = React.ComponentType<{ size?: number; color?: string }>

const thinkingTypeToIcon: Record<ThinkingType, IconCmp> = {
	[ThinkingType.REASONING]: ThinkingSvgAnimationExpo,
	[ThinkingType.GREP_CODEBASE]: FileSearchAnimationExpo,
	[ThinkingType.SEMANTIC_SEARCH]: FileSearchAnimationExpo,
	[ThinkingType.PACKAGE_DOCUMENTATION]: EyeAnimationExpo,
	[ThinkingType.ASSET_GENERATION]: AssetGenerationAnimationExpo,
	[ThinkingType.PROJECT_SETTINGS]: SettingsAnimationExpo,
	[ThinkingType.PRODUCT_DESIGN_ADVISOR]: RollerBrushAnimationExpo,
	[ThinkingType.BROWSER_USE]: CodeBrowserAnimationExpo,
	[ThinkingType.CURL]: CodeBrowserAnimationExpo,
	[ThinkingType.TEST_RUNNER]: ActivityAnimationExpo,
	[ThinkingType.URL_ACCESS]: SearchSmAnimationExpo,
	[ThinkingType.WEB_SEARCH]: GlobeAnimationExpo,
	[ThinkingType.SHELL]: Terminal,
	[ThinkingType.SCREENSHOT]: Camera
} as const

const thinkingTypeToStaticIcon: Record<ThinkingType, IconCmp> = {
	[ThinkingType.REASONING]: Lightbulb,
	[ThinkingType.GREP_CODEBASE]: FileSearch,
	[ThinkingType.SEMANTIC_SEARCH]: FileSearch,
	[ThinkingType.PACKAGE_DOCUMENTATION]: Eye,
	[ThinkingType.ASSET_GENERATION]: ImageIcon,
	[ThinkingType.PROJECT_SETTINGS]: Settings,
	[ThinkingType.PRODUCT_DESIGN_ADVISOR]: PaintRoller,
	[ThinkingType.BROWSER_USE]: PanelTop,
	[ThinkingType.CURL]: SquareTerminal,
	[ThinkingType.TEST_RUNNER]: Activity,
	[ThinkingType.URL_ACCESS]: Search,
	[ThinkingType.WEB_SEARCH]: Globe,
	[ThinkingType.SHELL]: Terminal,
	[ThinkingType.SCREENSHOT]: Camera
} as const

const LoadingIndicator = ({
	thinkingType,
	theme
}: {
	thinkingType: ThinkingType
	theme: Theme
}) => {
	if (thinkingType && thinkingType in thinkingTypeToIcon) {
		const Icon = thinkingTypeToIcon[thinkingType as ThinkingType]
		return <Icon size={18} color={colors[theme].gray[900]} />
	}
	return <PulsingDot />
}

const SuccessIndicator = ({
	thinkingType,
	theme
}: {
	thinkingType?: string
	theme: Theme
}) => {
	if (thinkingType && thinkingType in thinkingTypeToStaticIcon) {
		const Icon = thinkingTypeToStaticIcon[thinkingType as ThinkingType]
		return <Icon size={18} color={colors[theme].gray[900]} />
	}
	return <Check size={18} color={colors[theme].gray[900]} />
}

interface ThinkingStatusIndicatorProps {
	status: {
		isRunning: boolean
		isSuccess: boolean
		isCancelled: boolean
		isLatest?: boolean
	}
	data?: {
		domainsArray?: string[]
		thinkingType?: string
	}
}

export const ThinkingStatusIndicator = ({
	status,
	data
}: ThinkingStatusIndicatorProps) => {
	const { isRunning, isSuccess, isCancelled } = status
	const { domainsArray, thinkingType } = data ?? {}
	const { theme } = useTheme()

	if (isRunning) {
		return (
			<LoadingIndicator
				thinkingType={thinkingType as ThinkingType}
				theme={theme}
			/>
		)
	}

	if (isSuccess) {
		if (domainsArray && domainsArray.length > 0) {
			return (
				<SuccessIndicator
					thinkingType={ThinkingType.WEB_SEARCH}
					theme={theme}
				/>
			)
		}
		return <SuccessIndicator thinkingType={thinkingType} theme={theme} />
	}

	if (isCancelled) {
		return <X size={18} color={colors[theme].gray[400]} />
	}

	return <View style={styles.cancelledDot(theme)} />
}

const styles = defineStyles({
	cancelledDot: (theme: Theme) => ({
		width: 14,
		height: 14,
		borderRadius: 50,
		backgroundColor: colors[theme].gray[400]
	})
})
